import type { Handle } from '@sveltejs/kit';
import { dev } from '$app/environment';

// Headers that harden every response. The Content-Security-Policy itself (with per-request nonces)
// is generated by SvelteKit from `kit.csp` in svelte.config.js.
export const handle: Handle = async ({ event, resolve }) => {
  const response = await resolve(event);
  const headers = response.headers;

  headers.set('X-Content-Type-Options', 'nosniff');
  // CSP frame-ancestors is the real control; this covers browsers that only know the old header.
  headers.set('X-Frame-Options', 'DENY');
  headers.set('Referrer-Policy', 'strict-origin-when-cross-origin');
  headers.set('Permissions-Policy', 'camera=(), microphone=(), geolocation=(), payment=(), usb=()');
  headers.set('Cross-Origin-Opener-Policy', 'same-origin-allow-popups');
  if (!dev) {
    headers.set('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  }
  return response;
};
